#include <stdio.h>

void print_binary(int n) {
    int bits[32];
    int count = 0;
    while (n > 0) {
        bits[count++] = n % 2;
        n /= 2;
    }
    for (int i = count - 1; i >= 0; i--) {
        printf("%d", bits[i]);
    }
    printf("\n");
}

int main() {
    print_binary(13);
    return 0;
}
